(()=>{
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function disclosure(label,cls=''){const d=document.createElement('details');d.className='light-details '+cls;const s=document.createElement('summary');s.textContent=label;d.append(s);s.addEventListener('click',e=>e.stopPropagation());return d}
function refresh(){document.querySelectorAll('#risk-section .risk').forEach(r=>{const rows=[...r.querySelectorAll('tbody tr')].filter(e=>!e.hidden);const out=r.querySelector('.risk-brief');if(out)out.textContent=rows.length?rows[0].cells[5].textContent:'';const s=r.querySelector('.risk-disclosure>summary');if(s)s.textContent=`${r.querySelector(".risk-disclosure").open?"收起":"展开"}工单明细（${rows.length} 张）`});const more=document.querySelector('.due-more');if(more){const n=[...more.querySelectorAll('[data-workitem]')].filter(e=>!e.hidden).length;more.querySelector('summary').textContent=`查看其余 ${n} 张到期工单`;more.hidden=n===0}}
function enhance(){const delivery=document.querySelector('#delivery-tab');if(!delivery||delivery.dataset.light)return;delivery.dataset.light='true';
const guide=disclosure('统计口径与说明','scope-guide');const guideBody=document.createElement('div');guideBody.className='guide-body';guide.append(guideBody);document.querySelector('.action-scope').append(guide);
document.querySelectorAll('.action-metric').forEach(k=>{const note=k.querySelectorAll(':scope>.note')[1];if(note){const row=document.createElement('div');row.className='guide-row';row.innerHTML='<b>'+esc(k.querySelector(':scope>.note').textContent)+'</b>';row.append(note);guideBody.append(row)}});
document.querySelectorAll('#delivery-tab section>.section-head>div>.note').forEach(n=>{const row=document.createElement('div');row.className='guide-row';const title=n.closest('.section-head').querySelector('.section-title')?.textContent||'说明';row.innerHTML='<b>'+esc(title)+'</b>';row.append(n);guideBody.append(row)});
const legend=document.querySelector('.overdue-legend');if(legend){const row=document.createElement('div');row.className='guide-row';row.innerHTML='<b>逾期区间图例</b>';row.append(legend)}
const key=document.querySelector('#risk-section>.section-head>div');if(key){const extra=key.querySelector(':scope>div[style]');if(extra){const row=document.createElement('div');row.className='guide-row';row.innerHTML='<b>风险展示规则</b>';row.append(extra);guideBody.append(row)}}
document.querySelectorAll('#risk-section .risk').forEach(r=>{const table=r.querySelector('table');if(!table)return;const d=disclosure('展开工单明细','risk-disclosure');d.open=true;d.addEventListener('toggle',()=>{const count=[...d.querySelectorAll('tbody tr')].filter(row=>!row.hidden).length;d.querySelector('summary').textContent=(d.open?'收起':'展开')+'工单明细（'+count+' 张）'});table.before(d);d.append(table);const brief=document.createElement('p');brief.className='risk-brief';d.before(brief);const btn=document.createElement('button');btn.className='light-object';btn.type='button';btn.textContent='查看需求';btn.addEventListener('click',e=>{e.stopPropagation();r.click()});const actions=document.createElement('div');actions.className='light-actions';d.before(actions);actions.append(d,btn)});
document.querySelectorAll('.overdue-group').forEach(g=>{const track=g.querySelector('.overdue-track');if(track){const d=disclosure('区间示意','period-detail');track.before(d);d.append(track)}});
const timeline=document.querySelector('.due-timeline');if(timeline){const groups=[...timeline.querySelectorAll(':scope>.due-group')];const more=disclosure('查看其余到期工单','due-more');timeline.append(more);groups.slice(2).forEach(g=>more.append(g))}
const owner=document.querySelector('#risk-owner-section');if(owner){const d=document.createElement('details');d.className='owner-disclosure light-details';const s=document.createElement('summary');const head=owner.querySelector('.section-head');s.append(...head.childNodes);head.remove();d.append(s);d.append(...owner.childNodes);owner.append(d)}
refresh();}
const oldRender=render;render=function(){oldRender();enhance()};const oldFilters=applyFilters;applyFilters=function(){oldFilters();refresh()};enhance();
})();
